contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address logAddr, uint minSum) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);

        bool revertedBefore;
        c.SetLogFile(logAddr); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedBefore = true; } else { revertedBefore = false; }

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedAfter;
        c.SetLogFile(logAddr); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedAfter = true; } else { revertedAfter = false; }

        assert(!revertedBefore && revertedAfter);
    }

    receive() external payable {}
}

